/* Lote 2 do PDF: gabaritos provisórios, com correção científica posterior na vacina BCG intradérmica. */
EX.push(...[{"id":"pdf-lote2-1","name":"PDF LOTE 2 · CIRUGÍA (REVISIÓN PENDIENTE)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"cuál de las siguientes afirmaciones respecto a la valoración del dolor abdominal en un anciano es cierta:","o":["Comparado con los jóvenes, en los pacientes ancianos son menos frecuentes problemas como la apendicitis o colecistitis.","Para una misma causa de abdomen agudo, los ancianos tienen el mismo pronóstico que los jóvenes.","Comparado con los jóvenes, los ancianos tienen menos dolor y sensibilidad a la palpación abdominal, pero es más probable que tengan fiebre y leucocitosis.","En los ancianos, la forma atípica de presentación de la enfermedad y el retraso en el diagnóstico conducen a una mayor mortalidad que en los jóvenes."]},{"n":2,"q":"un paciente de 58 años que ingreso a guardia por dolor en hipocondrio derecho y epigastrio que irradia a dorso, fiebre con escalofríos e ictericia de 24 hs de evolución, deterioro progresivamente su estado general por lo cual es internado en terapia intensiva. laboratorio: leucocitosis aumento de fosfatasa alcalina y bilirrubina. en la ecografía se encuentra vesícula litiasica no distendida con vía biliar de 13mm y páncreas normal. de acuerdo a su sospecha diagnostica cual es la conducta más adecuada?","o":["Antibióticos de amplio espectro por vía parenteral y control evolutivo","Colecistectomía laparoscopia con colocación de tubo de kehr","Tratamiento antibiótico y drenaje endoscópico de la vía biliar","Colecistectomía abierta con exploración de la vía biliar."]},{"n":3,"q":"La colecistectomía laparoscópica tiene como ventaja sobre la colecistectomía por laparotomía:","o":["Permite conservar la vesícula.","La reducción de la estancia hospitalaria.","Es una técnica exenta de mortalidad.","No se asocia a lesiones de la vía biliar."]}]},{"id":"pdf-lote2-2","name":"PDF LOTE 2 · DIGESTIVO (REVISIÓN PENDIENTE)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"pct. femenina de 20 años consulta a la guardia por dolor abdominal en fosa iliaca derecha de 48 horas de evolución, fiebre y nauseas. blumberg negativo, dolor a la palpación en fosa iliaca y flanco derechos, sin defensa. laboratorio gb 11.500/mm3. pcr 35mg/l, su normal. bhcg negativa. tac de abdomen sin contraste informa, engrosamiento de colon ascendente y transverso, ganglios mesentéricos aumentados de tamaño y numero. ¿cuál es el diagnostico más probable en esta paciente?","o":["enfermedad de crohn","adenitis mesentérica","apendicitis aguda.","linfoma abdominal."]},{"n":2,"q":"Un hombre de 73 años consulta a la guardia por distensión abdominal y vómitos sin eliminación de gases ni materia fecal. El estudio radiológico de abdomen muestra asas de intestino delgado distendidas con niveles hidroaéreos y aire en la vía biliar intrahepática (aerobilia). ¿Cuál es el diagnóstico más probable?","o":["Íleo biliar","Fistula gastroyeyunocolonica","Colecistitis gangrenosa","Cáncer de colon derecho con perforación intestinal"]},{"n":3,"q":"Un hombre de 57 años lo consulta por presentar episodios de epigastralgia, eructos, plenitud gástrica precoz con predominio postprandial y vómitos ocasionales de 3 meses de evolución, No presenta antecedentes de intolerancia gástrica ni dolor abdominal. En el Interrogatorio surge una disfagia leve para sólidos y perdida de 4-5 kg de peso en los últimos 8 meses (8% del peso corporal). ¿Cuál sería la conducta más adecuada?","o":["Colon por enema doble contraste","Fibroendoscopia digestiva alta","Consejos dietarios y control en 3 meses","Ecografía abdominal y dieta blanda hipograsa"]},{"n":4,"q":"en el diagnóstico de carcinoma hepatocelular, señale la respuesta correcta:","o":["El estudio histológico es obligatorio en todos los casos","En pacientes cirróticos el dx se puede realizar mediante técnicas de imagenes dinâmicas","En pacientes cirróticos el dx se puede realizar ante la sospecha clinica y niveles de alfa fetoproteina > 100ng/dl","La arteriografia es la única que demuestra de forma fiable la característica fundamental de este tumor que es la hipervascularización arterial"]}]},{"id":"pdf-lote2-4","name":"PDF LOTE 2 · GINECOLOGÍA Y OBSTETRICIA (REVISIÓN PENDIENTE)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"paciente de 22 años con amenorrea de 9 semanas, nauseas intensas y sangrado vaginal. al examen: útero aumentado a tamaño compatible con 14 semanas. eco transvaginal: imagen en ¨conos de nieve¨, sin embrión visible. beta hcg 180.000 ui/ml. cual es el diagnóstico más probable?","o":["mola hidatiforme completa","mola parcial.","embarazo múltiple.","embarazo ectópico."]},{"n":2,"q":"Cuál de los siguientes MACs es el de menor efectividad?","o":["DIU.","ACO.","Preservativo masculino.","Diafragma"]},{"n":3,"q":"Concurre a la guardia una mujer de 26 años cursando su primer embarazo de 38 semanas por presentar contracciones. Se trata de una gestacion gemelar doble, bicorial biamniótico con ambos fetos en presentacion cefálica y buena vitalidad. Al examen obstétrico se encuentra en trabajo de parto, con el cuello uterino borrado y 7 cm de dilatación, membranas ovulares íntegras y buena dinámica uterina. ¿Cuál es la conducta más adecuada? *","o":["Cesárea de urgencia","Inducción del parto","Conducción del parto","Esperar el parto espontáneo"]},{"n":4,"q":"Cuál es el valor normal de la frecuencia cardiaca fetal? *","o":["100-140 latidos por minuto.","120-170 latidos por minuto.","110-160 latidos por minuto.","60-90 latidos por minuto."]},{"n":5,"q":"Ingresa por guardia una mujer cursando embarazo de 30 semanas, refiriendo que está perdiendo líquido claro por sus genitales desde el día de ayer. Al examen se constata feto vivo, salida de líquido amniótico con fetidez, temperatura axilar de 39 grados, frecuencia cardiaca materna 110 latidos por minuto. El examen de laboratorio informa leucocitosis, eritrosedimentacion acelerada y PCR reactiva. ¿Cuál es la conducta más adecuada?","o":["Control ambulatorio, antibióticos, antitérmicos y manejo expectante","Internación, cultivos, antibióticos, uteroinhibición parenteral y maduración pulmonar fetal con corticoides","Internación, antibióticos, ecografía, control de laboratorio cada 72 horas y finalizar el embarazo a la semana 34","Internación, antibióticos y finalización del embarazo"]},{"n":6,"q":"Se presenta a la guardia una mujer joven con dolor en fosa ilíaca derecha y fiebre. ¿Cuál debe ser el primer método diagnóstico de elección a solicitar?","o":["Ecografía abdominal pelviana.","La radiografía simple de abdomen","La ecografía transvaginal","La tomografía computarizada sin contraste IV"]},{"n":7,"q":"Una paciente de 57 años, con diagnóstico de carcinoma de mama, presenta en cuadrante superoexterno de mama izquierda nódulo de 2 cm de diámetro, consistencia duro pétrea, mama derecha sin particularidades, axilas libres. No se evidencian metástasis a distancia. ¿Cuál es la conducta inicial más adecuada?","o":["Quimioterapia neoadyuvante","Tumorectomía con ganglio centinela","Tumorectomía con linfadenectomía axilar","Mastectomía radical modificada"]},{"n":8,"q":"una paciente de 45 años consulta porque en una mamografía se le informa que presenta múltiples calcificaciones agrupadas menores a 2 mm de diámetro, irregulares distribuidas en el cuadrante superior externo de la mama. ¿cuál es la conducta inicial más adecuada ¿","o":["Control mamográfico en 6 meses","Completar estudio con ecografía mamaria","Punción biopsia histológica","Cuadrantectomia de mama derecha"]}]},{"id":"pdf-lote2-5","name":"PDF LOTE 2 · HEMATOLOGÍA (REVISIÓN PENDIENTE)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"Las características morfológicas de la anemia ferropénica son:","o":["VCM normal, HCM bajo, RDW bajo y RR bajo.","VCM bajo, HCM bajo, RDW alto y RR bajo.","VCM bajo, HCM bajo, RDW bajo y RR bajo.","VCM alto, HCM bajo, RDW alto y RR alto."]},{"n":2,"q":"La localización más frecuente de la trombosis venosa profunda es:","o":["Sector femoral en el muslo","Plexo venoso de los músculos soleos.","Sector ilíaco","Vena cava inferior"]}]},{"id":"pdf-lote2-6","name":"PDF LOTE 2 · INFECTOLOGÍA (REVISIÓN PENDIENTE)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"paciente en tratamiento antibiótico por infección grave presenta enrojecimiento, prurito, hipotensión y broncoespasmo, síndrome de hombre rojo. ¿cuál de los siguientes antibióticos produce este síndrome?","o":["tazobactam- piperacilina-tazobactam","vancomicina","cefepima","meropenem"]},{"n":2,"q":"Señale cuál es el efecto postvacunal más frecuente de la vacuna BCG. *","o":["Dolor, tumefacción y enrojecimiento local.","Formación de abscesos en el sitio de la aplicación.","Ulceración prolongada.","Adenopatías locales."]},{"n":3,"q":"¿Cuál de las siguientes vacunas es de aplicación intradérmica?","o":["Triple viral","Anti HVB","Anti neumococica conjugada.","BCG"]}]},{"id":"pdf-lote2-7","name":"PDF LOTE 2 · NEUROLOGÍA (REVISIÓN PENDIENTE)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"Un varón de 52 años es traído a la guardia por su esposa porque lo encontró en estado de estupor en la casa. Refiere que hace 30 minutos estaba bien y que comenzó a dolerle la cabeza y que tenía debilidad en la mitad derecha del cuerpo. Tiene antecedentes de hipertensión arterial en tratamiento con 25 mg/día de hidroclorotiazida. Al examen físico está somnoliento y casi no responde a las preguntas, la TA: 242-148 mm Hg, FC: 124 lpm, FR: 24 rpm, SatO2 es de 98% con aire ambiental y su temperatura es de 37.0°C. No mueve el brazo, ni la pierna derecha. Se realiza TC cerebral sin contraste que evidencia imagen hiperdensa que compromete el putamen izquierdo. ¿Cuál es el diagnóstico más probable?","o":["Tumoración encefálica.","Hemorragia intracraneal.","Accidente cerebrovascular isquémico en el territorio de la arteria cerebral media izquierda.","Hematoma subdural."]}]},{"id":"pdf-lote2-9","name":"PDF LOTE 2 · PEDIATRÍA (REVISIÓN PENDIENTE)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"Marcos de 5 meses, se alimenta a pecho exclusivo, presenta deposiciones líquidas y más frecuentes, de 2 días de evolución. Al examen físico el niño se encuentra vigil y reactivo, con mucosas húmedas, frecuencia cardíaca de 120 x min, frecuencia respiratoria de 30 x min, pulsos periféricos positivos y relleno capilar de 1 segundo. La madre refiere haber cambiado un pañal con orina hace una hora. ¿Cuál es la recomendación con respecto a la alimentación? *","o":["Continuar con la lactancia materna con más frecuencia.","Reemplazar lactancia materna por leche deslactosada.","Suspender la lactancia e hidratar con sales de la OMS.","Reemplazar la lactancia materna por leche maternizada."]},{"n":2,"q":"Un niño de 18 meses, tratado con amoxicilina por una faringitis, vuelve a la consulta por fiebre persistente de seis días de evolución de 39,8 °C. Presenta exantema maculopapular en tronco, inyección conjuntival, labios secos y agrietados. Las palmas de las manos eritematosas. ¿Cuál es el diagnóstico más probable? *","o":["Alergia a los antibióticos.","Síndrome de Kawasaki.","Escarlatina.","Sarampión."]},{"n":3,"q":"Señale cuál de las siguientes es la causa más frecuente de trasplante hepático en la infancia:","o":["Atresia biliar.","Hiperoxaluria primaria tipo I.","Enfermedad de Alagille.","Enfermedad de Crigler-Najjar de tipo I."]},{"n":4,"q":"nino de 4 anos presenta um TEC leve asintomatico com cefalohematoma frontal, cual es la conducta inicial a seguir?","o":["Analgésicos, crioterapia, internacion y rx de cráneo","Analgésicos, crioterapia y pautas de alarma","TAC de cerebro sin contraste e interconsulta con neurología","Analgésicos, crioterapia y oxigeno"]},{"n":5,"q":"cuál es la complicación evolutiva más frecuente en la meningitis bacteriana en la edad pediátrica?","o":["Hipoacusia","Retraso mental","Hidrocefalia","Defectos visuales"]},{"n":6,"q":"niño de 4 años de edad que consulta por aparición a lo largo de los últimos tres días de lesiones cutáneas en las piernas y glúteos. sus padres refieran que su pediatra le había diagnosticado una infección de vía respiratoria superiores 10 días antes. en las últimas 12 horas presenta dolor abdominal intenso tipo cólico y ha realizado dos deposiciones diarreicas. afebril no pérdida de peso. a la exploración presenta numerosas petequias y lesiones purpuricas palpables de predominio en glúteos y extremidades inferiores. buen estado general, aunque tiene dolor abdominal intenso. la palpación abdominal es difícil de valorar por dolor difuso. no viceromegalias. no otros hallazgos de interés a la exploración. ¿cuál de los siguientes datos no apoya su sospecha diagnostica?","o":["Artritis de rodilla y tobillo","Hematuria","Plaquetopenia","Sangre oculta en heces"]}]},{"id":"pdf-lote2-10","name":"PDF LOTE 2 · NEFROLOGÍA (REVISIÓN PENDIENTE)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"Una mujer de 68 años presenta desde hace 3 meses una alteración en la función renal detectada por índice urinario proteína/creatinina. se atiende en el centro de salud de forma irregular desde hace 5 años por hipertensión arterial. no fuma, no tiene diabetes y no realiza actividad física. En la consulta se constata: ta 145-90 mm/hg, imc 28,67 kg/m2 y en el laboratorio presenta: colesterol: total 200 mg/dl, ldl100 mg/dl y velocidad de filtración glomerular 75 ml/min/1,73m2. según la “guía de práctica clínica sobre prevención y detección precoz de la enfermedad renal crónica en el primer nivel de atención”, ¿cuál es la conducta más adecuada? (muni 2018, 18)","o":["Control de los factores de riesgo cardiovascular; estabilizar la tensión arterial y agregar medicación con inhibidores de la enzima convertidora de angiotensina (ieca).","Estabilizar la tensión arterial con medidas farmacológicas y no farmacológicas; indicar dieta hipoproteica, hiposódica e hipokalémica y realizar interconsulta con nefrología.","Derivar al servicio de nefrología y seguimiento en el segundo nivel de atención.","Control de los factores de riesgo cardiovascular; estabilizar la tensión arterial con medidas farmacologías y no farmacológicas; indicar dieta hipoproteica y agregar estatinas."]}]},{"id":"pdf-lote2-11","name":"PDF LOTE 2 · NEUMONOLOGÍA (REVISIÓN PENDIENTE)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"Un paciente de 80 años con antecedentes de insuficiencia renal crónica y diabetes tipo 2, presenta desde hace 3 días tos con expectoración purulenta, fiebre, dificultad respiratoria y dolor torácico derecho en puntada de costado. En la exploración presenta una presión arterial de 120-60mmHg FC :80 lpm y FR:20rpm. La SO2 es de 94% al aire ambiente. Esta febril y algo somnoliento. Se auscultan crepitantes en base pulmonar derecha y la rx de tórax muestra condensación con broncograma aéreo en dicha localización. ¿Cuál de las siguientes considera la conducta más apropiada?","o":["Le prescribe levofloxacina 500mg VO cada 24 horas, reposo, hidratación y cita a control en 48 horas","Indica amoxicilina – clavulánico VO 1 gr cada 12 horas, reposo y cita a control en 48 horas","Decide internación en clínica médica y luego tomarle hemocultivos, inicia ceftriaxona 2 gr IV día","Decide internación en clínica médica y luego tomarle hemocultivos, inicia imipenem 250mg IV cada 6 horas"]},{"n":2,"q":"Una paciente de 22 años con diagnóstico de asma bronquial hace 6 meses concurre al consultorio para control. Se encuentra en tratamiento con agonistas b2 a demanda. Refiere síntomas asmáticos frecuentes, 4 veces en el último mes y sin episodios de exacerbaciones. ¿Cuál es el tratamiento más adecuado? (CABA 2017, 82)","o":["Budesonide.","Combinación budesonide/formoterol.","Combinación formoterol/ tiotropio.","Formoterol."]},{"n":3,"q":"¿Cuál es la conducta más adecuada con un paciente de 35 años, sin antecedentes patológicos, que fue tratado por una bronquitis aguda con amoxicilina 500 mg cada 8 horas durante 10 días y consulta por la persistencia de tos no productiva una semana después de haber finalizado el tratamiento? (ÚNICO 2017, 99)","o":["Indicar loratadina 10 mg día por 3 días.","Explicar que la tos se resolverá espontáneamente.","Solicitar radiografía de tórax.","Indicar levofloaxacina 700 mg día por 5 días."]},{"n":4,"q":"Cuál de las siguientes afirmaciones con respecto a las características clínicas de la neumonía que presenta un anciano frágil comparada con un adulto con mismo diagnostico?","o":["Puede presentar clínicamente en forma de delirium","Tienen el mismo riesgo de sufrir perdida de sus capacidades de autocuidado","En el anciano frágil requiere mayor grado de reposo o permanencia en cama para evitar complicaciones","La edad modifica la antibioticoterapia empírica de la neumonía adquirida en la comunidad."]},{"n":5,"q":"Una mujer de 74 años, sin antecedentes patológicos, refiere durante la consulta que su esposo continuamente le está diciendo que ella no oye bien, especialmente en las reuniones familiares. ¿Cuál es la conducta inicial más adecuada?","o":["Solicitar audiometría.","Solicitar interconsulta con fonoaudiología.","Conducta expectante y evaluar evolución.","Realizar otoscopía"]},{"n":6,"q":"Respecto a las bronquiectasias, indique la opción correcta:","o":["Es un proceso fibrotico que mejora con corticoides rápidamente.","Es un proceso fibro-inflamatorio crónico con alteración de las paredes bronquiales.","Es un proceso donde hay aumento de la vasculatura bronquial principalmente distal.","Es un proceso inflamatorio agudo con alteración de la estructura alveolar."]}]},{"id":"pdf-lote2-13","name":"PDF LOTE 2 · TOXICOLOGÍA (REVISIÓN PENDIENTE)","year":"Novas do PDF · por especialidade","qs":[{"n":1,"q":"además de la hemorragia, un efecto adverso grave de la heparina es:","o":["Hipopotasemia","Alcalosis metabólica","Diarrea","Trombocitopenia"]}]}]);
